1	import fs from "node:fs";
2	import path from "node:path";
3	import os from "node:os";
4	import type {PeerId} from "@libp2p/interface/peer-id";
5	import {createSecp256k1PeerId} from "@libp2p/peer-id-factory";
6	import {Multiaddr} from "@multiformats/multiaddr";
7	import {createKeypairFromPeerId, SignableENR} from "@chainsafe/discv5";
8	import {Logger} from "@lodestar/utils";
9	import {exportToJSON, readPeerId} from "../../config/index.js";
10	import {writeFile600Perm} from "../../util/file.js";
11	import {parseListenArgs} from "../../options/beaconNodeOptions/network.js";
12	import {BeaconArgs} from "./options.js";
13	
14	/**
15	 * Check if multiaddr belongs to the local network interfaces.
16	 */
17	export function isLocalMultiAddr(multiaddr: Multiaddr | undefined): boolean {
18	  if (!multiaddr) return false;
19	
20	  const protoNames = multiaddr.protoNames();
21	  if (protoNames.length !== 2 && protoNames[1] !== "udp") {
22	    throw new Error("Invalid udp multiaddr");
23	  }
24	
25	  const interfaces = os.networkInterfaces();
26	  const tuples = multiaddr.tuples();
27	  const family = tuples[0][0];
28	  const isIPv4: boolean = family === 4;
29	  const ip = tuples[0][1];
30	
31	  if (!ip) {
32	    return false;
33	  }
34	
35	  const ipStr = isIPv4
36	    ? Array.from(ip).join(".")
37	    : Array.from(Uint16Array.from(ip))
38	        .map((n) => n.toString(16))
39	        .join(":");
40	
41	  for (const networkInterfaces of Object.values(interfaces)) {
42	    for (const networkInterface of networkInterfaces || []) {
43	      // since node version 18, the netowrkinterface family returns 4 | 6 instead of ipv4 | ipv6,
44	      // even though the documentation says otherwise.
45	      // This might be a bug that would be corrected in future version, in the meantime
46	      // the check using endsWith ensures things work in node version 18 and earlier
47	      if (String(networkInterface.family).endsWith(String(family)) && networkInterface.address === ipStr) {
48	        return true;
49	      }
50	    }
51	  }
52	
53	  return false;
54	}
55	
56	/**
57	 * Only update the enr if the value has changed
58	 */
59	function maybeUpdateEnr<T extends "ip" | "tcp" | "udp" | "ip6" | "tcp6" | "udp6">(
60	  enr: SignableENR,
61	  key: T,
62	  value: SignableENR[T] | undefined
63	): void {
64	  if (enr[key] !== value) {
65	    enr[key] = value;
66	  }
67	}
68	
69	export function overwriteEnrWithCliArgs(
70	  enr: SignableENR,
71	  args: BeaconArgs,
72	  logger: Logger,
73	  opts?: {newEnr?: boolean; bootnode?: boolean}
74	): void {
75	  const preSeq = enr.seq;
76	  const {port, discoveryPort, port6, discoveryPort6} = parseListenArgs(args);
77	  maybeUpdateEnr(enr, "ip", args["enr.ip"] ?? enr.ip);
78	  maybeUpdateEnr(enr, "ip6", args["enr.ip6"] ?? enr.ip6);
79	  maybeUpdateEnr(enr, "udp", args["enr.udp"] ?? discoveryPort ?? enr.udp);
80	  maybeUpdateEnr(enr, "udp6", args["enr.udp6"] ?? discoveryPort6 ?? enr.udp6);
81	  if (!opts?.bootnode) {
82	    maybeUpdateEnr(enr, "tcp", args["enr.tcp"] ?? port ?? enr.tcp);
83	    maybeUpdateEnr(enr, "tcp6", args["enr.tcp6"] ?? port6 ?? enr.tcp6);
84	  }
85	
86	  function testMultiaddrForLocal(mu: Multiaddr, ip4: boolean): void {
87	    const isLocal = isLocalMultiAddr(mu);
88	    if (args.nat) {
89	      if (isLocal) {
90	        logger.warn("--nat flag is set with no purpose");
91	      }
92	    } else {
93	      if (!isLocal) {
94	        logger.warn(
95	          `Configured ENR ${ip4 ? "IPv4" : "IPv6"} address is not local, clearing ENR ${ip4 ? "ip" : "ip6"} and ${
96	            ip4 ? "udp" : "udp6"
97	          }. Set the --nat flag to prevent this`
98	        );
99	        if (ip4) {
100	          enr.delete("ip");
101	          enr.delete("udp");
102	        } else {
103	          enr.delete("ip6");
104	          enr.delete("udp6");
105	        }
106	      }
107	    }
108	  }
109	  const udpMultiaddr4 = enr.getLocationMultiaddr("udp4");
110	  if (udpMultiaddr4) {
111	    testMultiaddrForLocal(udpMultiaddr4, true);
112	  }
113	  const udpMultiaddr6 = enr.getLocationMultiaddr("udp6");
114	  if (udpMultiaddr6) {
115	    testMultiaddrForLocal(udpMultiaddr6, false);
116	  }
117	
118	  if (enr.seq !== preSeq) {
119	    // If the enr is newly created, its sequence number can be set to 1
120	    // It's especially clean for fully configured bootnodes whose enrs never change
121	    // Otherwise, we can increment the sequence number as little as possible
122	    if (opts?.newEnr) {
123	      enr.seq = BigInt(1);
124	    } else {
125	      enr.seq = preSeq + BigInt(1);
126	    }
127	    // invalidate cached signature
128	    delete enr["_signature"];
129	  }
130	}
