59	export function getNetworkData(network: NetworkName): {
60	  chainConfig: ChainConfig;
61	  depositContractDeployBlock: number;
62	  genesisFileUrl: string | null;
63	  bootnodesFileUrl: string | null;
64	  bootEnrs: string[];
65	} {
66	  switch (network) {
67	    case "mainnet":
68	      return mainnet;
