70	      return dev;
71	    case "gnosis":
72	      return gnosis;
73	    case "goerli":
74	      return goerli;
75	    case "ropsten":
76	      return ropsten;
77	    case "sepolia":
78	      return sepolia;
79	    case "holesky":
80	      return holesky;
81	    case "chiado":
82	      return chiado;
83	    case "ephemery":
84	      return ephemery;
85	    default:
86	      throw Error(`Network not supported: ${network}`);
87	  }
