101	/**
102	 * Fetches the latest list of bootnodes for a network
103	 * Bootnodes file is expected to contain bootnode ENR's concatenated by newlines
104	 */
105	export async function fetchBootnodes(network: NetworkName): Promise<string[]> {
106	  const bootnodesFileUrl = getNetworkData(network).bootnodesFileUrl;
107	  if (bootnodesFileUrl === null) {
108	    return [];
109	  }
110	
111	  const bootnodesFile = await got.get(bootnodesFileUrl).text();
112	  return parseBootnodesFile(bootnodesFile);
113	}
114	
115	export async function getNetworkBootnodes(network: NetworkName): Promise<string[]> {
116	  const bootnodes = [...getNetworkData(network).bootEnrs];
117	
118	  // Hidden option for testing
119	  if (!process.env.SKIP_FETCH_NETWORK_BOOTNODES) {
120	    try {
121	      const bootEnrs = await fetchBootnodes(network);
122	      bootnodes.push(...bootEnrs);
123	    } catch (e) {
124	      // eslint-disable-next-line no-console
125	      console.error(`Error fetching latest bootnodes: ${(e as Error).stack}`);
126	    }
127	  }
128	
129	  return bootnodes;
130	}
