## Import Section

```javascript
import fs from "node:fs";
import path from "node:path";
import os from "node:os";
import type {PeerId} from "@libp2p/interface";
import {createSecp256k1PeerId} from "@libp2p/peer-id-factory";
import {Multiaddr} from "@multiformats/multiaddr";
import {createPrivateKeyFromPeerId, SignableENR} from "@chainsafe/enr";
import {Logger} from "@lodestar/utils";
import {exportToJSON, readPeerId} from "../../config/index.js";
import {writeFile600Perm} from "../../util/file.js";
import {parseListenArgs} from "../../options/beaconNodeOptions/network.js";
import {BeaconArgs} from "./options.js";
```

## Usage of the Three Functions

`SignableENR`, `createPrivateKeyFromPeerId`, and related helpers come from the `@chainsafe/enr` package. Here is how they are used together:

**Creating a new ENR** — a private key is derived from a peer ID and passed to the V4 factory:
```javascript
const enr = SignableENR.createV4(createPrivateKeyFromPeerId(peerId).privateKey);
```

**Decoding a stored ENR from text** — the persisted ENR string is parsed, again supplying the derived private key:
```javascript
enr = SignableENR.decodeTxt(fs.readFileSync(enrFile, "utf-8"), createPrivateKeyFromPeerId(peerId).privateKey);
```

In both cases, `createPrivateKeyFromPeerId(peerId).privateKey` supplies the signing key material tied to the peer identity.

## The `isLocalMultiAddr` Function

```javascript
export function isLocalMultiAddr(multiaddr: Multiaddr | undefined): boolean {
  if (!multiaddr) return false;

  const protoNames = multiaddr.protoNames();
  if (protoNames.length !== 2 && protoNames[1] !== "udp") {
    throw new Error("Invalid udp multiaddr");
  }

  const interfaces = os.networkInterfaces();
  const tuples = multiaddr.tuples();
  const family = tuples[0][0];
  const isIPv4: boolean = family === 4;
  const ip = tuples[0][1];

  if (!ip) {
    return false;
  }

  const ipStr = isIPv4
    ? Array.from(ip).join(".")
    : Array.from(Uint16Array.from(ip))
        .map((n) => n.toString(16))
        .join(":");

  for (const networkInterfaces of Object.values(interfaces)) {
    for (const networkInterface of networkInterfaces || []) {
      if (String(networkInterface.family).endsWith(String(family)) && networkInterface.address === ipStr) {
        return true;
      }
    }
  }

  return false;
}
```

**How it works:** The function returns `false` immediately if no multiaddr is passed. It validates that the address is a UDP multiaddr, then reads the system's network interfaces. It extracts the IP family and address bytes from the multiaddr tuples, formatting them as either a dotted IPv4 string or a colon-separated hexadecimal IPv6 string. It then iterates over all local interfaces and returns `true` when both the family and address match a local interface.

